158	func traceStepNodesToSteps(nodes []*traceStepNode, parentName string) []traceStep {
159		sortTraceStepNodes(nodes, parentName)
160	
161		steps := make([]traceStep, 0, len(nodes))
162		for _, node := range nodes {
163			step := node.step
164			step.SubSteps = traceStepNodesToSteps(node.children, step.Name)
165			steps = append(steps, step)
166		}
167		return steps
168	}
