170	func sortTraceStepNodes(nodes []*traceStepNode, parentName string) {
171		slices.SortFunc(nodes, func(a, b *traceStepNode) int {
172			if parentName == "" {
173				return cmp.Compare(a.step.Name, b.step.Name)
174			}
175	
176			aIdx, aNumeric := traceStepChildIndex(parentName, a.step.Name)
177			bIdx, bNumeric := traceStepChildIndex(parentName, b.step.Name)
178			if aNumeric && bNumeric {
179				return cmp.Compare(aIdx, bIdx)
180			}
181			if aNumeric {
182				return -1
183			}
184			if bNumeric {
185				return 1
186			}
187			return cmp.Compare(a.step.Name, b.step.Name)
188		})
